def count_squares(lines: List[str]) -> int:
    def is_square(corners: List[Tuple[int, int]], side_length: int) -> bool:
        # Check if all corners are present
        for i in range(side_length):
            for j in range(side_length):
                if (corners[0][0] + i, corners[0][1] + j) not in corners:
                    return False
        # Check if all sides are present
        for i in range(side_length):
            if (corners[0][0] + i, corners[0][1]) not in corners or \
               (corners[0][0], corners[0][1] + i) not in corners or \
               (corners[0][0] + i, corners[0][1] + side_length) not in corners or \
               (corners[0][0] + side_length, corners[0][1] + i) not in corners:
                return False
        return True

    height = len(lines)
    width = len(lines[0])
    square_count = 0

    for i in range(height):
        for j in range(width):
            if lines[i][j] == '+':
                for side_length in range(2, min(height - i, width - j) + 1):
                    corners = [(i, j), (i, j + side_length - 1), (i + side_length - 1, j), (i + side_length - 1, j + side_length - 1)]
                    if is_square(corners, side_length):
                        square_count += 1

    return square_count
